content.solution_code:
class Tool {
  constructor(brand) {
    this.brand = brand;
  }

  use() {
    return `This ${this.brand} tool is being used.`;
  }
}

class Hammer extends Tool {
  constructor(brand, material) {
    super(brand);
    this.material = material;
  }

  use() {
    return `This ${this.brand} Hammer (${this.material}) is pounding.`;
  }
}

